class Integration(BaseModel):
    """
    Credential/Auth for a specific cloud instance.

    Example: Shelly account "A", HomeAssistant instance "Home".
    """

    config: Annotated[
        Any | None,
        Field(description="Provider-specific non-secret configuration (JSON)."),
    ] = None
    enabled: Annotated[
        bool,
        Field(
            description="User-controlled flag: if false, this integration will not be used for actions/ops."
        ),
    ]
    health: Annotated[
        IntegrationHealth,
        Field(description="Backend-controlled health marker (ok/error)."),
    ]
    id: Annotated[str, Field(description="Unique identifier (ULID).")]
    metadata: dict[str, str] | None = None
    name: Annotated[
        LocalizedString,
        Field(
            description="Human-friendly name for this integration (distinguishes multiple integrations of same provider)."
        ),
    ]
    org_id: Annotated[
        str, Field(description="Organization that owns this integration.")
    ]
    provider_type: Annotated[
        ProviderType,
        Field(description="Provider type (e.g. homeassistant, shelly_cloud)."),
    ]


class IntegrationResponse1(Integration):
    provider_type_name: Annotated[
        LocalizedString,
        Field(description="Human-friendly provider type name(s), keyed by locale."),
    ]


class IntegrationResponse2(StorageFeatures, IntegrationResponse1):
    pass


class IntegrationResponse(RootModel[IntegrationResponse2]):
    root: IntegrationResponse2


class InviteScheduleSnapshot(BaseModel):
    active_window: InviteWindow | None = None
    is_recurring: bool
    next_window: InviteWindow | None = None
    series_end: (
        InviteRecurrenceSeriesEnd1
        | InviteRecurrenceSeriesEnd2
        | InviteRecurrenceSeriesEnd3
        | None
    ) = None
    slot_duration_seconds: int


class ListDevicesQuery(MultiResourceOutputOptionsQuery, PaginationQuery):
    device_kind: Annotated[
        str | None,
        Field(
            description="Optional filter: only devices with metadata.kind equal to this value (e.g. virtual_access_portal).\nRequires integration_id. Filtering done at SQL level."
        ),
    ] = None
    external_id: Annotated[
        str | None,
        Field(
            description="Optional filter: only devices with this external_id. Requires integration_id and device_kind.\nReturns at most 1 device. Filtering done at SQL level."
        ),
    ] = None
    has_external_id: Annotated[
        bool | None,
        Field(
            description="When true, only devices with a non-empty `external_id`. Requires `integration_id`."
        ),
    ] = None
    has_go2rtc_channel: Annotated[
        bool | None,
        Field(
            description="When true, only devices whose metadata JSON has a non-empty `channel` (go2rtc cameras). Requires `integration_id`."
        ),
    ] = None
    include_stale: Annotated[
        bool | None,
        Field(
            description="When true with `integration_id`, include `stale` per device when the provider supports it."
        ),
    ] = None
    integration_id: Annotated[
        str | None,
        Field(
            description="Optional filter: only devices belonging to this integration."
        ),
    ] = None
    q: Annotated[
        str | None,
        Field(
            description="Case-insensitive substring match on localized device name (JSON). Best-effort when `integration_id` is set (SQL ILIKE)."
        ),
    ] = None


